/** Only finalized provider observations may appear as in-progress scoped PRs.
 * A journal payload is not a merge/synchronization proof and must also match
 * the persisted owner's exact branch, epoch and direct target before publication. */
function scopedPullFromOperation(operation: Row, execution: Row, group: Row): PullRequestRecord | undefined {
  if (operation.status !== "finalized" || !["pull.create", "pull.merge", "pull.close", "pull.update"].includes(String(operation.kind))) return undefined;
  const isFinal = execution.expected_head_sha !== undefined;
  const expectedBase = isFinal ? group.integration_target : group.group_branch;
  if (operation.owner_execution_id !== execution.execution_id ||
    operation.ownership_epoch !== execution.ownership_epoch ||
    (isFinal && (execution.execution_branch !== group.group_branch ||
      execution.integration_target !== expectedBase ||
      operation.expected_head !== execution.expected_head_sha))) return undefined;
  const value = parseJson<unknown>(operation.remote_fact_json, null);
  if (!value || typeof value !== "object" || Array.isArray(value)) return undefined;
  const fact = value as Record<string, unknown>;
  const statuses = new Set(["open", "conflicted", "closed", "merged", "unknown"]);
  if (typeof fact.id !== "string" || !fact.id ||
    typeof fact.providerNumber !== "number" || !Number.isSafeInteger(fact.providerNumber) || fact.providerNumber <= 0 ||
    typeof fact.htmlUrl !== "string" || typeof fact.observedAt !== "string" || !fact.observedAt ||
    typeof fact.headSha !== "string" || !/^[0-9a-f]{40}$/i.test(fact.headSha) ||
    fact.ownerExecutionId !== execution.execution_id ||
    fact.head !== execution.execution_branch || fact.base !== expectedBase ||
    fact.headSha !== operation.expected_head || fact.base !== operation.expected_base ||
    !statuses.has(String(fact.status)) ||
    (fact.mergeCommitSha !== undefined &&
      (typeof fact.mergeCommitSha !== "string" || !/^[0-9a-f]{40}$/i.test(fact.mergeCommitSha)))) return undefined;
  try {
    const url = new URL(fact.htmlUrl);
    if (url.protocol !== "https:" || url.username || url.password) return undefined;
  } catch { return undefined; }
  return {
    id: fact.id,
    providerNumber: fact.providerNumber,
    htmlUrl: fact.htmlUrl,
    head: String(fact.head),
    base: String(fact.base),
    ownerExecutionId: String(fact.ownerExecutionId),
    status: fact.status as PullRequestRecord["status"],
    headSha: fact.headSha,
    ...(typeof fact.mergeCommitSha === "string" ? { mergeCommitSha: fact.mergeCommitSha } : {}),
    observedAt: fact.observedAt
  };
}

